#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Define a struct to hold the Roman numeral values
typedef struct {
    char *symbol;
    int value;
} RomanNumeral;

// Function to convert Roman numerals to integers
int romanToInt(char *s) {
    int result = 0;
    RomanNumeral romanNumerals[] = {
        {"M", 1000},
        {"CM", 900},
        {"D", 500},
        {"CD", 400},
        {"C", 100},
        {"XC", 90},
        {"L", 50},
        {"XL", 40},
        {"X", 10},
        {"IX", 9},
        {"V", 5},
        {"IV", 4},
        {"I", 1}
    };
    int i = 0;
    while (*s) {
        for (i = 0; i < 13; i++) {
            if (strncmp(s, romanNumerals[i].symbol, strlen(romanNumerals[i].symbol)) == 0) {
                result += romanNumerals[i].value;
                s += strlen(romanNumerals[i].symbol);
                break;
            }
        }
    }
    return result;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <Roman numeral string>\n", argv[0]);
        return 1;
    }
    char *romanNumeral = argv[1];
    int result = romanToInt(romanNumeral);
    printf("%d\n", result);
    return 0;
}
